import re
from taf.rfrl.procedures.resources.python.logger import (
    log_step,
    log_result,
    log_input_and_output,
    log_env_state,
)

from taf.rfrl.procedures.resources.python.counters.core.interface import (
    Core,
)

from taf.rfrl.procedures.resources.python.admin_info_model.admin_info_model import (
    get_mrbts_id_admin,
)

from taf.rfrl.procedures.resources.python.counters.bts.exceptions import (
    VoltageMeasurementValueIncorrect,
    PmCounterIncorrectValue,
    UnexpectedEnergyConsumptionChange,
    MeanEnergyConsumptionValueEqualsZero,
    IncorrectNumberOfMeasurements,
    CounterNotFound,
)


class BtsCounters(Core):
    def __init__(self):
        super(BtsCounters, self).__init__()

    def load_energy_monitoring_counters(self, list_of_ru_ids, timeout=180):
        """
        Loads Energy Monitoring Counters (M40003C0 - M40003C5) via api
        for specific list of RMODs.

        :param list_of_ru_ids: list of RMODs for which counters should be loaded
        :param timeout: timeout for get_counters_info operation

        :type list_of_ru_ids: list(int)
        :type timeout: int

        :return: dict(str: dict)
        """
        log_step("Getting BTS energy monitoring counters dictionary via API...")
        mrbts_id = get_mrbts_id_admin(connection=self.api_connection_alias)
        energy_monitoring_counters = {}
        self.load_counters(timeout=timeout)

        for ru_id in list_of_ru_ids:
            try:
                energy_monitoring_counters[f"RMOD-{ru_id}"] = self.counters["BTS"][
                    f"MRBTS-{mrbts_id}"][f"RMOD-{ru_id}"]["SBTS_RFM_Energy_Monitoring"]
            except KeyError:
                energy_monitoring_counters[f"RMOD-{ru_id}"] = self.counters[f"MRBTS-{mrbts_id}"][
                    "EQM-1"]["APEQM-1"][f"RMOD-{ru_id}"]["SBTS_RFM_Energy_Monitoring"]

        log_result("BTS Energy Monitoring Counters read successfully")

        return energy_monitoring_counters

    def load_energy_consumption_counters(self, timeout=600):
        """
        Loads energy consumption counters (M40002C0, M40002C1 and M40002C2) via api

        :param timeout: timeout for get_counters_info operation
        :type timeout: int

        :return: Energy Consumption Counters
        :rtype: dict
        """
        log_step("Getting BTS energy consumption counters dictionary via API...")
        mrbts_id = get_mrbts_id_admin(connection=self.api_connection_alias)
        self.load_counters(timeout=timeout)

        try:
            energy_consumption_counters = self.counters["BTS"][f"MRBTS-{mrbts_id}"]["SBTS_Energy_Consumption"]
        except KeyError:
            energy_consumption_counters = self.counters[f"MRBTS-{mrbts_id}"]["SBTS_Energy_Consumption"]

        log_result("BTS Energy Consumption Counters read successfully")

        return energy_consumption_counters

    def load_system_module_energy_monitoring_counters(self, list_of_smod_ids, timeout=180):
        """
        Loads Energy Monitoring Counters (M40004C0 - M40004C5) via api
        for specific list of SMODs.

        :param list_of_smod_ids: list of SMODs for which counters should be loaded
        :type list_of_smod_ids: list(int)
        :param timeout: timeout for get_counters_info operation
        :type timeout: int

        :return: dict(str: dict)
        """
        log_step("Getting system module energy monitoring counters dictionary via API...")
        mrbts_id = get_mrbts_id_admin(connection=self.api_connection_alias)
        energy_monitoring_counters = {}
        self.load_counters(timeout=timeout)

        for smod_id in list_of_smod_ids:
            try:
                energy_monitoring_counters[f"SMOD-{smod_id}"] = self.counters["SMOD"][
                    f"SMOD-{smod_id}"]["CABINET-1"]["SBTS_SM_Energy_Monitoring"]
            except KeyError:
                energy_monitoring_counters[f"SMOD-{smod_id}"] = self.counters[f"MRBTS-{mrbts_id}"][
                    "EQM-1"]["APEQM-1"]["CABINET-1"][f"SMOD-{smod_id}"]["SBTS_SM_Energy_Monitoring"]

        log_result("SMOD Energy Monitoring Counters read successfully")

        return energy_monitoring_counters

    def verify_energy_consumption_counters_for_specific_time_interval(
        self, deviation, verification_startpoint, verification_endpoint, counters_to_verify=None,
    ):
        """
        Performs verification of energy consumption counters for the specific time interval
        between verification_startpoint and verification_endpoint

        :param deviation: max allowed deviation from the mean value of counters
        :type deviation: float
        :param verification_startpoint: timestamp of the verification starting point
        :type verification_startpoint: str
        :param verification_endpoint: timestamp of the verification ending point
        :type verification_endpoint: str
        :param counters_to_verify: list of counters to verify, None by default which will be translated
                                   to ["M40002C0", "M40002C1"]
        :type counters_to_verify: list of str
        """
        energy_consumption_counters = self.load_energy_consumption_counters()
        log_env_state(
            "Current energy consumption counters: {}".format(
                str(energy_consumption_counters)
            )
        )

        verification_startpoint_unix, verification_endpoint_unix = self._convert_timestamp_to_unix(
            verification_startpoint, verification_endpoint
        )

        if counters_to_verify is None:
            counters_to_verify = ["M40002C0", "M40002C1"]

        for counter in counters_to_verify:

            self.verify_given_energy_consumption_counter(
                deviation=deviation,
                counter_name=counter,
                energy_consumption_counters_dict=energy_consumption_counters,
                startpoint=verification_startpoint_unix,
                endpoint=verification_endpoint_unix,
            )

        log_result("BTS Energy Consumption Counters verification Complete!")

    def verify_given_energy_consumption_counter(
            self,
            deviation,
            counter_name,
            energy_consumption_counters_dict,
            startpoint,
            endpoint,
    ):
        """
        Verifies the given energy_consumption_counters_dict by picking the measurements
        taken between the desired time interval between startpoing and endpoint, calculating their
        mean and checking if there are any measurements with values exceeding allowed deviation.

        :param deviation: max allowed deviation from the mean value of counters
        :type deviation: float
        :param counter_name: name of the counter that needs to be verified
        :type counter_name: str
        :param energy_consumption_counters_dict: dict with all energy consumption counters
        :type energy_consumption_counters_dict: dict(str, dict(str, int)
        :param startpoint: starting timestamp for the verification in UNIX format
        :type startpoint: float
        :param endpoint: finishing timestamp for the verification in UNIX format
        :type endpoint: float

        :raises: MeanEnergyConsumptionValueEqualsZero when mean value of the counters is 0.0
        :raises: UnexpectedEnergyConsumptionChange when one of the counters
        exceeds the allowed deviation

        """
        energy_consumption_counters_list = self._get_values_of_counter_from_specific_time_period(
            energy_consumption_counters_dict, counter_name, startpoint, endpoint
        )
        log_env_state(
            "Current energy consumption counters: {}".format(
                str(energy_consumption_counters_list)
            )
        )

        mean_counters_value, min_value, max_value = self._calculate_range(
            energy_consumption_counters_list, deviation
        )

        if mean_counters_value == 0.0:
            raise MeanEnergyConsumptionValueEqualsZero(
                "All reported values of counter {0} are zero!".format(counter_name)
            )
        for value in energy_consumption_counters_list:
            if value not in range(int(min_value), int(max_value)):
                raise UnexpectedEnergyConsumptionChange(
                    "Value's {0} difference from the mean value {1:.2f} "
                    "exceeds the allowed deviation {2}% "
                    "for counter {3}".format(
                        value, mean_counters_value, deviation * 100, counter_name
                    )
                )
        log_result("Verification of counter {0} complete!".format(counter_name))

    @log_input_and_output
    def check_if_first_counters_are_smaller(self, first_counters, second_counters):
        """
        Compares values of two sets of counters.
        Values in second_counters should be bigger than first_counters.
        :param first_counters: list of dicts with counters values which should have smaller values
        :type first_counters: list(dict(str, int))
        :param second_counters: list of dicts with counters values which should have bigger values
        :type second_counters: list(dict(str, int))
        :raises ValueError: when value of counter in second_counters is smaller or equal to value in first_counters
        """
        for second_counters, first_counters in zip(second_counters, first_counters):
            for counter, values in first_counters.items():
                for first_value, second_value in zip(values, second_counters[counter]):
                    if first_value >= second_value:
                        raise ValueError(
                            "Value of counter {0}: {1} is greater or equal to: {2}".format(
                                counter,
                                second_value,
                                first_value,
                            )
                        )
        log_result("Counters verification Complete!")

    @staticmethod
    def _calculate_range(energy_consumption_counters_list, deviation):
        mean_counters_value = sum(energy_consumption_counters_list) / len(
            energy_consumption_counters_list
        )
        min_value = mean_counters_value * (1 - deviation)
        max_value = mean_counters_value * (1 + deviation)

        return mean_counters_value, min_value, max_value

    @log_input_and_output
    def verify_energy_monitoring_counters_for_specific_ru_ids(self, list_of_ru_ids,
                                                              verification_startpoint,
                                                              verification_endpoint):
        """
        Verifies PM counters that are responsible for energy monitoring: M40003C0 - M40003C5
        According to CB007086 RU nominal voltage range should be 40500mV-57000mV
        Counters are reported always on the full minute, so if verification_startpoint given is
        for example '2022-11-23 18:15:11.276042', it will be adjusted to '2022-11-23 18:15:00.00'
        not to miss the first measurement.

        :param list_of_ru_ids: list of RMODs for which verification will be performed
        :type list_of_ru_ids: list(int)
        :param verification_startpoint: timestamp of the verification starting point
        :type verification_startpoint: str
        :param verification_endpoint: timestamp of the verification ending point
        :type verification_endpoint: str
        """
        energy_monitoring_counters = self.load_energy_monitoring_counters(
            list_of_ru_ids
        )
        log_env_state(str(energy_monitoring_counters))

        verification_startpoint = self._adjust_verification_startpoint(
            verification_startpoint=verification_startpoint)

        verification_startpoint_unix, verification_endpoint_unix = self._convert_timestamp_to_unix(
            verification_startpoint, verification_endpoint
        )

        self._verify_energy_monitoring_counters(energy_monitoring_counters=energy_monitoring_counters,
                                                verification_startpoint_unix=verification_startpoint_unix,
                                                verification_endpoint_unix=verification_endpoint_unix)
        log_result("BTS Energy Counters verification Complete!")

    @log_input_and_output
    def verify_energy_monitoring_counters_for_smods(self, list_of_smod_ids, verification_startpoint,
                                                    verification_endpoint, number_of_measurements):
        """
        Verifies PM counters that are responsible for SMOD energy monitoring: M40004C0 - M40004C5
        Counters are reported always on the full minute, so if verification_startpoint given is
        for example '2022-11-23 18:15:11.276042', it will be adjusted to '2022-11-23 18:15:00.00'
        not to miss the first measurement.

        :param list_of_smod_ids: list of SMODs for which verification will be performed
        :type list_of_smod_ids: list(int)
        :param verification_startpoint: timestamp of the verification starting point
        :type verification_startpoint: str
        :param verification_endpoint: timestamp of the verification ending point
        :type verification_endpoint: str
        :param number_of_measurements: expected number of measurements for smod counters
        :type number_of_measurements: int
        """
        energy_monitoring_counters = self.load_system_module_energy_monitoring_counters(
            list_of_smod_ids
        )
        log_env_state(str(energy_monitoring_counters))

        verification_startpoint = self._adjust_verification_startpoint(
            verification_startpoint=verification_startpoint)

        verification_startpoint_unix, verification_endpoint_unix = self._convert_timestamp_to_unix(
            verification_startpoint, verification_endpoint
        )

        self._verify_smod_energy_monitoring_counters(energy_monitoring_counters=energy_monitoring_counters,
                                                     verification_startpoint_unix=verification_startpoint_unix,
                                                     verification_endpoint_unix=verification_endpoint_unix,
                                                     number_of_measurements=number_of_measurements)
        log_result("SMOD Energy Counters verification Complete!")

    @staticmethod
    def get_number_of_measurements(collection_time, monitoring_interval=15):
        """
        Gets expected number of measurements in specified collection_time
        :param collection_time: time of counters collection in minutes, e.g. "45min"
        :type collection_time: str
        :param monitoring_interval: interval of counters collection in minutes, 15 by default
        :type monitoring_interval: int
        :return: expected number of measurements
        :rtype: int
        """
        return int(int(re.findall(r'\d+', collection_time)[0]) / monitoring_interval)

    @staticmethod
    def convert_counter_results_to_dictionary(counters_results):
        """
        Converts bts counters results to dictionary format.
        :param counters_results: list of counters results, e.g.: [{'M55601C02001': [1.0]}, {'M55601C02002': [900.0]}]
        :type counters_results: list

        :return: dictionary with counters results, e.g.: {'M55601C02001': [1.0], 'M55601C02002': [900.0]}
        :rtype: dict
        """
        return {list(result.keys())[0]: list(result.values())[0] for result in counters_results}

    def get_counter_values_from_results_dictionary(self, counters_results, counter_id, component_name=None):
        """
        Gets counter values from counters results dictionary.
        :param counters_results: dictionary with counters results,
                                 e.g.: {'NRCELL-1/NDLSQ/M55301C10001': [729734.0],
                                        'NRCELL-1/NDLSQ/M55301C10002': [133984.0],
                                        'NRCELL-1/NDLSQ/M55301C10003': [661.0],
                                        'NRCELL-1/NDLSQ/M55301C10004': [2855.0],
                                        'NRCELL-1/NRRCC/M55124C00001': [0.0]}
        :type counters_results: dict
        :param counter_id: counter id to get values from dictionary, e.g.: 'M55601C02001'
        :type counter_id: str
        :param component_name: component name to get counter values from dictionary, e.g.: 'NRCELL-1'.
                               Defaults to None means that component name is not used in search and first matching counter
                               id is returned.
        :type component_name: str
        :return: counter values
        :rtype: list

        :raises CounterNotFound: when counter with given id (and component name if provided) is not found
        """
        for counter_name, counter_value in counters_results.items():
            counter_name_parts = counter_name.split("/")
            if counter_name_parts[-1] == counter_id and (not component_name or counter_name_parts[0] == component_name):
                return counter_value

        raise CounterNotFound(f"Counter '{counter_id}'"
                              + (f" with component name '{component_name}' " if component_name else " ")
                              + "not found in counters results dictionary.")

    @staticmethod
    def _adjust_verification_startpoint(verification_startpoint):
        startpoint_second = verification_startpoint.split(":")[-1]
        if float(startpoint_second) > 0.0:
            return verification_startpoint.replace(startpoint_second, '00.00')

        return verification_startpoint

    def _verify_energy_monitoring_counters(self,
                                           energy_monitoring_counters,
                                           verification_startpoint_unix,
                                           verification_endpoint_unix):

        for ru_id, counters in energy_monitoring_counters.items():
            for counter_id, values in counters.items():
                for timestamp, counter_value in values.items():
                    if verification_startpoint_unix <= int(timestamp) <= verification_endpoint_unix:
                        if counter_id == "M40003C0":
                            self._verify_min_input_voltage_in_rf_counter(
                                counter_value=counter_value,
                                timestamp=timestamp,
                                ru_id=ru_id,
                            )
                        if counter_id == "M40003C1":
                            self._verify_max_input_voltage_in_rf_counter(
                                counter_value=counter_value,
                                timestamp=timestamp,
                                ru_id=ru_id,
                            )
                        elif counter_id != "M40003C0" and counter_id != "M40003C1":
                            self._verify_energy_monitoring_counter(
                                counter_value=counter_value,
                                timestamp=timestamp,
                                counter_id=counter_id,
                                ru_id=ru_id,
                            )

    def _verify_smod_energy_monitoring_counters(self,
                                                energy_monitoring_counters,
                                                verification_startpoint_unix,
                                                verification_endpoint_unix,
                                                number_of_measurements):
        counters_in_timeframe = {}

        for smod_id, counters in energy_monitoring_counters.items():
            for counter_id, values in counters.items():
                for timestamp, counter_value in values.items():
                    if verification_startpoint_unix <= int(timestamp) <= verification_endpoint_unix:
                        if smod_id in counters_in_timeframe:
                            if counter_id in counters_in_timeframe[smod_id]:
                                counters_in_timeframe[smod_id][counter_id].append(counter_value)
                            else:
                                counters_in_timeframe[smod_id][counter_id] = [counter_value]
                        else:
                            counters_in_timeframe[smod_id] = {counter_id: [counter_value]}

        self._verify_counters_number(counters_in_timeframe, number_of_measurements)

    @staticmethod
    def _verify_counters_number(counters_in_timeframe, number_of_measurements):
        for smod, counters in counters_in_timeframe.items():
            for counter, values in counters.items():
                if len(values) != number_of_measurements:
                    raise IncorrectNumberOfMeasurements("Incorrect number of measurements for counter {}. "
                                                        "Number of collected measurements: {}, expected_number: {}.".
                                                        format(counter, len(values), number_of_measurements))

    @staticmethod
    def _verify_min_input_voltage_in_rf_counter(counter_value, timestamp, ru_id):
        if float(counter_value) < 40500:
            raise VoltageMeasurementValueIncorrect(
                "Voltage value for counter M40003C0 for "
                "{0} from timestamp {1} is too low: {2} mV! (voltage should be in range 40500-57000mV)".format(
                    ru_id, timestamp, counter_value
                )
            )

    @staticmethod
    def _verify_max_input_voltage_in_rf_counter(counter_value, timestamp, ru_id):
        if float(counter_value) > 57000:
            raise VoltageMeasurementValueIncorrect(
                "Voltage value for counter M40003C1 for "
                "{0} from timestamp {1} is too high: {2} mV! (voltage should be in range 40500-57000mV)".format(
                    ru_id, timestamp, counter_value
                )
            )

    @staticmethod
    def _verify_energy_monitoring_counter(counter_value, timestamp, counter_id, ru_id):
        if float(counter_value) == 0.0:
            raise PmCounterIncorrectValue(
                "Value of counter {0} for {1} from timestamp {2} equals zero!".format(counter_id, ru_id, timestamp)
            )
